/*
 * A164568  Primes p such that 9*p-10 and 9*p+10 are prime numbers.
 * https://oeis.org/A164568
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 14, u16 n <= 522, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   grow_seq, is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A164568:  Primes p such that 9p-10 and 9p+10 are also prime.
 *  The sequence is generated by scanning primes and keeping those for
 *  which both 9p-10 and 9p+10 are prime.  No closed form is known,
 *  so a search is required.  The function is memoised on a static
 *  cache so that arbitrary ordering of calls works efficiently.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/is_prime.h"
#include "../utils/grow_seq.h"

/* Return the nth term (n>=1) of the sequence.  The index is 1‑based as
 * in the OEIS entry.  Behaviour for n<1 is unspecified. */
seq_t a(idx_t n)
{
    /* static state for memoisation */
    static seq_t *cache = NULL;   /* array of found terms          */
    static size_t cap   = 0;      /* current capacity of cache     */
    static size_t len   = 0;      /* number of terms stored        */
    static idx_t  next  = 2;      /* next integer to test as prime */

    if (n == 0)                    /* undefined behaviour below offset */
        return 0;

    /* Ensure we have at least n terms in the cache. */
    while (len < (size_t)n) {
        idx_t p;

        /* Find the next prime candidate. */
        do {
            p = next;
            ++next;
        } while (!is_prime(p));

        /* Check the twin‑prime‑like condition. */
        idx_t q1 = 9 * p - 10;
        if (!is_prime(q1))
            continue;
        idx_t q2 = 9 * p + 10;
        if (!is_prime(q2))
            continue;

        /* Add the discovered prime to the cache. */
        if (len + 1 > cap)
            grow_seq(&cache, &cap, len + 1);
        cache[len++] = (seq_t)p;
    }

    return cache[n - 1];
}
